import { realpathSync, lstatSync } from 'node:fs';
import { homedir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
const root = process.env.MEDIFLOW_AMBULATORIO_HOME ?? join(homedir(), '.mediflow-ambulatorio');
const info = lstatSync(root);
if (!info.isDirectory() || info.uid !== process.getuid() || (info.mode & 0o7777) !== 0o700) 
  throw Error('MEDIFLOW_AMBULATORIO_SETUP_REQUIRED');

const file = join(realpathSync(root), 'launcher.mjs');
const metadata = lstatSync(file);
if (!metadata.isFile() || metadata.uid !== process.getuid() || metadata.nlink !== 1 || (metadata.mode & 0o7777) !== 0o600) 
  throw Error('MEDIFLOW_AMBULATORIO_SETUP_REQUIRED');
await import(pathToFileURL(file).href);
